#Mitxt2 on
on 1:INPUT:*:{
  if ($left($1,1) != /) {
    var %i 1, %a, %c.ini, %c.med, %c.fin, %v, %len, %1, %2, %3
    %c.ini = 13
    %c.med = 13
    %c.fin = 12
    while ($gettok($1-,%i,32)) { %v = $v1
      if (($hget(corrector,%v)) || (%v isnum)) { %a = %a $iif(%v isnum,%v,$v1) | goto fin }
      if (%v ison $chan) { %a = %a %v | goto fin }
      %1 = $upper($left(%v,1)) | %2 = $mid(%v,2,-1) | %3 = $right(%v,1))
      %len = $len(%v)
      if (3 &gt; %len) { %a = %a $+($chr(15),$chr(2),$chr(3),%c.ini,%1,$chr(2),$chr(3),%c.fin,$mid(%v,2-2,1000))  }
      else { %a = %a $+($chr(15),$chr(2),$chr(3),%c.ini,%1,$chr(2),$chr(3),%c.med,%2,$chr(2),$chr(3),%c.fin,%3) }
      :fin | inc %i
    }
    say %a | %frase^halt = on
  }
}

#Mitxt2 end
menu * {
  Colorea Letras
  .. On: .enable #mitxt2
  .. Off: .disable #mitxt2
}

